import type { DeviceEntry, DeviceRegistry } from '@thermal-label/contracts';
import { DEVICES, PROTOCOL_TAGS, REGISTRY, type DeviceKey } from './devices.generated.js';
import type { NiimbotEngineCapabilities } from './types.js';

/**
 * The niimbot device registry: one entry per model in niimbluelib's
 * model library, plus what `data/overlay.json5` adds. Generated by
 * `scripts/compile-data.mjs`.
 */
export const REGISTRY_NIIMBOT = REGISTRY as unknown as DeviceRegistry;

export { DEVICES, type DeviceKey };

/** Every engine protocol tag the registry uses. */
export const PROTOCOLS: ReadonlySet<string> = new Set(PROTOCOL_TAGS);

/** Find a device by registry key (= niimbluelib `PrinterModel` name). */
export function findDevice(key: string): DeviceEntry | undefined {
  return (DEVICES as Record<string, DeviceEntry | undefined>)[key];
}

/** Driver-specific capabilities of a device's primary engine. */
export function engineCapabilities(entry: DeviceEntry): NiimbotEngineCapabilities {
  return entry.engines[0]?.capabilities as NiimbotEngineCapabilities;
}

/** Find a device by the model ID it reports in `PrinterInfo`. */
export function findDeviceByModelId(modelId: number): DeviceEntry | undefined {
  return REGISTRY_NIIMBOT.devices.find(entry =>
    engineCapabilities(entry).modelIds.includes(modelId),
  );
}

/**
 * Find a device by advertised Bluetooth name. Only matches models with a
 * hand-checked prefix in the overlay. The longest prefix wins.
 */
export function findDeviceByName(name: string): DeviceEntry | undefined {
  let best: { entry: DeviceEntry; length: number } | undefined;
  for (const entry of REGISTRY_NIIMBOT.devices) {
    const prefix = entry.transports['bluetooth-gatt']?.namePrefix;
    if (prefix === undefined || !name.startsWith(prefix)) continue;
    if (!best || prefix.length > best.length) best = { entry, length: prefix.length };
  }
  return best?.entry;
}
